css:
& body { background-color: var(--bg); background-image: radial-gradient(ellipse at 4% 0%, var(--haze-mint), transparent 60%), radial-gradient(ellipse at 95% 5%, var(--haze-butter), transparent 52%), linear-gradient(145deg, var(--haze-blue), transparent 62%); background-attachment: fixed; min-height: 100vh; }
& .am-head { border-inline-start: 2px solid var(--signal-mint); padding-inline-start: 14px; }
& .am-head h1 { font-family: var(--font-sans); font-size: calc(28px * var(--am-scale, 1)); line-height: 1.3; font-weight: 650; letter-spacing: -0.025em; color: var(--title-1); text-shadow: none; }
& .am-head h1::before { content: "// "; color: var(--title-2); font-family: var(--font-mono); font-size: 0.72em; font-weight: 500; letter-spacing: -0.08em; }
& .am-panel { position: relative; border-color: var(--line); border-top-color: color-mix(in srgb, var(--signal-mint) 48%, var(--line)); }
& .am-panel::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 1.5px; background: linear-gradient(105deg, var(--signal-mint), var(--signal-butter) 66%, transparent); box-shadow: 0 0 7px var(--signal-glow); opacity: 0.58; pointer-events: none; }
& .am-panel-head { border-bottom-width: 1px; background: linear-gradient(115deg, var(--header-wash), transparent 80%); }
& .am-panel-head h2 { font-family: var(--font-sans); font-weight: 600; letter-spacing: -0.015em; color: var(--title-2); }
& .am-panel-id { border-radius: 5px; min-width: 24px; height: 24px; margin: 9px 0 9px 14px; font-size: calc(11px * var(--am-scale, 1)); font-weight: 600; font-family: var(--font-mono); border: 1px solid color-mix(in srgb, var(--signal-mint) 40%, transparent); }
& .am-md { line-height: 1.72; }
& .am-md h1 { color: var(--title-1); }
& .am-md h2 { color: var(--title-2); }
& .am-md h3 { color: var(--title-3); font-weight: 600; }
& .am-md h4 { color: var(--title-4); }
& .am-md h5 { color: var(--title-5); font-size: calc(12px * var(--am-scale, 1)); line-height: 1.5; margin: 14px 0 6px; }
& .am-md h6 { color: var(--title-6); font-size: calc(12px * var(--am-scale, 1)); line-height: 1.5; margin: 14px 0 6px; }
& .am-md h3::before { content: "> "; color: var(--accent); font-family: var(--font-mono); }
& .am-md strong, & .am-intro strong { color: var(--priority); font-weight: 650; }
& .am-md a { text-underline-offset: 3px; text-decoration-thickness: 1px; }
& .am-md blockquote { border-inline-start: 2px solid var(--accent); }
& .am-md th { color: var(--accent); font-weight: 600; }
& .am-kv { border-color: var(--line); border-radius: var(--radius); overflow: hidden; }
& .am-callout { border-radius: 7px; }
& .am-callout--err .am-callout-title { color: var(--priority); }
@media (max-width: 760px) { & .am-head h1 { font-size: calc(24px * var(--am-scale, 1)); } }
@media print { & body { background: var(--paper); min-height: auto; } & .am-head h1 { text-shadow: none; } & .am-panel { box-shadow: none; } & .am-panel::before { display: none; } }
/* Candidate long-document navigation spacing */
& .am-panel { scroll-margin-top: 80px; }
@media (max-width: 760px) { & .am-head { margin-top: 60px; } & .am-panel { scroll-margin-top: 110px; } }
